"""Complete SQL-text adapter for the offline synthetic order dataset."""
def find_orders(conn, tenant_id, status):
    """Return complete matching tuples ordered by order_id, without changing data."""
    if not isinstance(tenant_id, str) or not isinstance(status, str):
        raise TypeError("tenant_id and status must be strings")

    def encode_sql_literal(s):
        return "'" + s.replace("'", "''") + "'"

    sql = f"SELECT order_id, tenant_id, customer, amount, status FROM orders WHERE tenant_id = {encode_sql_literal(tenant_id)} AND status = {encode_sql_literal(status)} ORDER BY order_id"

    cursor = conn.execute(sql)
    return cursor.fetchall()
